// src/app/api/token/[mint]/route.ts
import type { NextRequest } from 'next/server';
import { isAddress } from '@solana/kit';

export const maxDuration = 15; // seconds (Hobby max 300). runtime defaults to 'nodejs'.

const NO_STORE = { 'Cache-Control': 'no-store' };

export async function GET(_req: NextRequest, { params }: { params: Promise<{ mint: string }> }) {
  const { mint } = await params; // params is a Promise in Next 15+/16
  if (!isAddress(mint)) {
    return Response.json({ error: 'invalid_mint' }, { status: 400, headers: NO_STORE });
  }

  const upstream = await fetch(`https://example-provider.invalid/tokens/${mint}`, {
    cache: 'no-store',                 // don't use Next's data cache for live data
    signal: AbortSignal.timeout(8_000),
  });
  if (!upstream.ok) {
    // 5xx is never cached by Vercel's CDN anyway; be explicit
    return Response.json({ error: 'upstream', status: upstream.status }, { status: 502, headers: NO_STORE });
  }
  const data: unknown = await upstream.json();

  return Response.json(data, {
    headers: {
      // Browser: always revalidate (gets forwarded as-is)
      'Cache-Control': 'public, max-age=0, must-revalidate',
      // Vercel edge only (consumed by Vercel, never forwarded): fresh 5s, serve stale up to 25s while refreshing in background
      'Vercel-CDN-Cache-Control': 'public, s-maxage=5, stale-while-revalidate=25',
    },
  });
}
// Check on a deployment: curl -sI https://<deploy>/api/token/<mint> | grep -i x-vercel-cache  -> MISS, then HIT / STALE
// Must NOT be sent/returned: Authorization request header, Set-Cookie, Vary: Cookie (all disable CDN caching).

// src/app/api/stream/route.ts
export const maxDuration = 60; // <= 300 on Hobby. Provisioned memory is billed while open.

export async function GET(request: Request) {
  const enc = new TextEncoder();
  let timer: ReturnType<typeof setInterval> | undefined;
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(enc.encode('retry: 3000\n\n')); // EventSource reconnect delay
      timer = setInterval(() => {
        controller.enqueue(enc.encode(`event: ping\ndata: ${Date.now()}\n\n`));
      }, 15_000);
      request.signal.addEventListener('abort', () => {
        clearInterval(timer);
        try { controller.close(); } catch {}
      });
    },
    cancel() { clearInterval(timer); },
  });
  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream; charset=utf-8',
      'Cache-Control': 'no-cache, no-transform',
      'X-Accel-Buffering': 'no',
    },
  });
}

'use client';
import { useEffect, useRef } from 'react';
import {
  createChart, CandlestickSeries, HistogramSeries, ColorType, CrosshairMode,
  type IChartApi, type ISeriesApi, type MouseEventParams, type CandlestickData, type UTCTimestamp,
} from 'lightweight-charts';

export type Candle = { t: number /* unix SECONDS, bucket open */; o: number; h: number; l: number; c: number; v: number };

const SUB = '₀₁₂₃₄₅₆₇₈₉';
export function formatMicroPrice(p: number, sig = 4): string {
  if (!Number.isFinite(p)) return '—';
  if (p === 0) return '0';
  const sign = p < 0 ? '-' : '';
  const a = Math.abs(p);
  if (a >= 1) return sign + a.toLocaleString('en-US', { maximumFractionDigits: a >= 1000 ? 2 : 4 });
  let zeros = -Math.floor(Math.log10(a)) - 1;
  let digits = Math.round(a * 10 ** (zeros + sig));
  if (digits >= 10 ** sig) { zeros -= 1; digits = Math.round(digits / 10); }
  if (zeros < 0) return sign + '1';
  const body = String(digits).padStart(sig, '0').replace(/0+$/, '') || '0';
  if (zeros >= 4) return `${sign}0.0${[...String(zeros)].map((d) => SUB[+d]).join('')}${body}`;
  return `${sign}0.${'0'.repeat(zeros)}${body}`;
}
// exact power of ten for LWC price-scale base (never pass minMove like 1e-9: 1/1e-9 is inexact -> 'unexpected base')
const priceBase = (ref: number, sig = 4) =>
  ref > 0 ? 10 ** Math.max(2, Math.min(18, -Math.floor(Math.log10(ref)) + sig)) : 100;

const toBar = (k: Candle): CandlestickData<UTCTimestamp> => ({ time: k.t as UTCTimestamp, open: k.o, high: k.h, low: k.l, close: k.c });
const toVol = (k: Candle) => ({ time: k.t as UTCTimestamp, value: k.v, color: k.c >= k.o ? 'rgba(22,199,132,0.45)' : 'rgba(234,57,67,0.45)' });
const sortDedupe = (rows: Candle[]) => {
  const m = new Map<number, Candle>();
  for (const r of rows) m.set(r.t, r); // last write wins
  return [...m.values()].sort((a, b) => a.t - b.t); // prod build does NOT validate order
};

export function PriceChart({ candles, live, onHover }: { candles: Candle[]; live?: Candle | null; onHover?: (c: CandlestickData | null) => void }) {
  const el = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const candleRef = useRef<ISeriesApi<'Candlestick'> | null>(null);
  const volRef = useRef<ISeriesApi<'Histogram'> | null>(null);
  const lastT = useRef<number>(0);

  useEffect(() => {
    if (!el.current) return;
    const chart = createChart(el.current, {
      autoSize: true,
      layout: { background: { type: ColorType.Solid, color: '#0b0e11' }, textColor: '#8b95a5', fontSize: 11, attributionLogo: true },
      grid: { vertLines: { color: 'rgba(255,255,255,0.04)' }, horzLines: { color: 'rgba(255,255,255,0.04)' } },
      crosshair: { mode: CrosshairMode.Normal },
      rightPriceScale: { borderVisible: false },
      timeScale: { timeVisible: true, secondsVisible: false, borderVisible: false, rightOffset: 4 },
      localization: { locale: 'en-US', priceFormatter: formatMicroPrice },
    });
    const candle = chart.addSeries(CandlestickSeries, {
      upColor: '#16c784', downColor: '#ea3943', borderVisible: false, wickUpColor: '#16c784', wickDownColor: '#ea3943',
      priceFormat: { type: 'custom', formatter: formatMicroPrice, base: 1e6 },
    });
    // Overlay volume at the bottom 20% (alternative: 3rd arg paneIndex=1 + chart.panes()[1].setHeight(90))
    const volume = chart.addSeries(HistogramSeries, { priceFormat: { type: 'volume' }, priceScaleId: '', lastValueVisible: false, priceLineVisible: false });
    volume.priceScale().applyOptions({ scaleMargins: { top: 0.8, bottom: 0 } });
    candle.priceScale().applyOptions({ scaleMargins: { top: 0.08, bottom: 0.24 } });

    const onMove = (p: MouseEventParams) => {
      const d = p.time ? (p.seriesData.get(candle) as CandlestickData | undefined) : undefined;
      onHover?.(d ?? null);
    };
    chart.subscribeCrosshairMove(onMove);
    chartRef.current = chart; candleRef.current = candle; volRef.current = volume;
    return () => {
      chart.unsubscribeCrosshairMove(onMove);
      chart.remove(); // StrictMode double-mount safe
      chartRef.current = null; candleRef.current = null; volRef.current = null;
    };
  }, [onHover]);

  // full history
  useEffect(() => {
    const c = candleRef.current, v = volRef.current;
    if (!c || !v) return;
    const rows = sortDedupe(candles);
    const last = rows.at(-1);
    if (last) c.applyOptions({ priceFormat: { type: 'custom', formatter: formatMicroPrice, base: priceBase(last.c) } });
    c.setData(rows.map(toBar));
    v.setData(rows.map(toVol));
    lastT.current = last?.t ?? 0;
    chartRef.current?.timeScale().fitContent();
  }, [candles]);

  // live tick: same bucket -> replaces last bar, newer bucket -> appends; older -> would throw, so skip
  useEffect(() => {
    if (!live || live.t < lastT.current) return;
    candleRef.current?.update(toBar(live));
    volRef.current?.update(toVol(live));
    lastT.current = live.t;
  }, [live]);

  return <div ref={el} className="h-[420px] w-full" />;
}

import { address, isAddress, getAddressEncoder, getProgramDerivedAddress, getBase58Decoder, type Address } from '@solana/kit';

const PUMP_PROGRAM = address('6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P');
const ATA_PROGRAM = address('ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL');
const TOKEN_PROGRAM = address('TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA');
const enc = getAddressEncoder();

export async function pumpBondingCurvePda(mint: Address) {
  // string seeds are UTF-8 encoded; returns readonly [Address, bump]
  const [pda] = await getProgramDerivedAddress({ programAddress: PUMP_PROGRAM, seeds: ['bonding-curve', enc.encode(mint)] });
  return pda; // e.g. mint 2qEHj…tpump -> 2JUXSuq1A1EdBzZj757cXFYuALPxv6vee4X981ajpzo8 (bump 254)
}

export async function associatedTokenAddress(owner: Address, mint: Address, tokenProgram: Address = TOKEN_PROGRAM) {
  const [ata] = await getProgramDerivedAddress({ programAddress: ATA_PROGRAM, seeds: [enc.encode(owner), enc.encode(tokenProgram), enc.encode(mint)] });
  return ata;
}

// Plain TS: base64 account data -> u64 little-endian (no library)
export function b64ToBytes(b64: string): Uint8Array {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}
export function readU64LE(bytes: Uint8Array, offset: number): bigint {
  return new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getBigUint64(offset, true);
}
export function decodePumpCurve(b64: string) {
  const b = b64ToBytes(b64);
  return {
    virtualTokenReserves: readU64LE(b, 8),   // raw, 6 decimals
    virtualSolReserves: readU64LE(b, 16),    // lamports
    realTokenReserves: readU64LE(b, 24),
    realSolReserves: readU64LE(b, 32),
    tokenTotalSupply: readU64LE(b, 40),
    complete: b[48] === 1,
    creator: b.length >= 81 ? getBase58Decoder().decode(b.subarray(49, 81)) : null,
  };
}
// bigint -> decimal string without precision loss
export function formatUnits(v: bigint, decimals: number): string {
  const base = 10n ** BigInt(decimals);
  const frac = (v % base).toString().padStart(decimals, '0').replace(/0+$/, '');
  return frac ? `${v / base}.${frac}` : `${v / base}`;
}
// isAddress('…') is a sync type guard; getProgramDerivedAddress needs crypto.subtle (https/localhost in browsers).

